'use strict';
window.classroomActive=false;window.classroomData=null;let schoolToken=window.StudentMemory.restore(),schoolPending=false,schoolOnline=true,schoolQuiz='daily',schoolPoll=null,schoolRefreshing=null;
const baseSchoolRender=render,baseSchoolPanel=renderPanel,baseSchoolSave=save,baseWeather=weather,baseMarket=marketOpen,baseBlocked=farmBlocked,baseQuiz=quiz;
const classroomBar=document.createElement('div');classroomBar.className='classroom-bar';classroomBar.hidden=true;document.querySelector('header').after(classroomBar);
const items=['상추','우유','사과','생선','당근','토마토','감자','딸기'];const symbols=['🥬','🥛','🍎','🐟','🥕','🍅','🥔','🍓'];const schoolTradeStock=i=>i<4?state.stock[i]:(state.garden?.stock?.[i-3]||0);
function coldChainPanel(atMarket=false){
 const store=state.logistics||{warehouse:[0,0,0,0],shipment:null},shipment=store.shipment,conditions=classroomData.shipping||{reasons:[]};
 if(atMarket&&!shipment)return '';
 const kind=shipment?items[shipment.item]:'물건',stage=shipment?.status;
 const caption=stage==='packed'?'보냉 포장 완료':stage==='checked'?'안전 경로·전력 확인 완료':stage==='in_transit'?'냉장 배송 중':'수확물을 냉장창고에 보관';
 const warning=conditions.reasons.length?`<p class="cold-warning" role="status">⛔ ${conditions.reasons.map(escapeHtml).join('<br>')}</p>`:'';
 const button=(action,label,disabled=false)=>`<button type="button" data-cold-action="${action}" ${disabled||schoolPending?'disabled':''}>${label}</button>`;
 if(atMarket)return `<section class="cold-chain-card"><b>🚚 냉장 배송 · 장터 인계</b><p>${kind} ${shipment.qty}개 · ${caption}</p>${warning}${stage==='in_transit'?button('shipment_arrive','장터에 도착 · 교환 재고로 인계',!!conditions.reasons.length||!classroomData.room.market):'<p>차량이 출발하면 이곳에서 인계할 수 있어요.</p>'}</section>`;
 const options=items.slice(0,4).map((name,i)=>{const available=(store.warehouse?.[i]||0)+(state.stock?.[i]||0);return `<option value="${i}" ${i===3&&available?'selected':''}>${symbols[i]} ${name} · 포장 가능 ${available}개</option>`}).join('');
 return `<section class="cold-chain-card" aria-label="냉장 유통"><b>🐟 수확 → 포장 → 안전 확인 → 배송 → 장터</b><p>냉장창고 생선 ${store.warehouse?.[3]||0}개 · 장터 생선 ${state.stock?.[3]||0}개</p><p class="cold-step">${caption}${shipment?` · ${kind} ${shipment.qty}개`:''}</p>${warning}${shipment?`<div class="cold-actions">${stage==='packed'?button('shipment_check','안전 경로·전력 확인',!!conditions.reasons.length):''}${stage==='checked'?button('shipment_dispatch','냉장 배송차 출발',!!conditions.reasons.length):''}${stage==='in_transit'?'<p>장터로 이동해 물건을 인계해 주세요. 이동 중에는 보관함과 교환에서 사용할 수 없어요.</p>':''}${button('shipment_cancel','배송 취소 · 원래 보관함으로')}</div>`:`<div class="cold-pack"><label>포장할 물건<select id="coldItem">${options}</select></label><label>수량<input id="coldQty" type="number" min="1" max="50" value="1"></label>${button('shipment_pack','보냉상자에 포장')}</div>`}</section>`;
}

function requestId(){return Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('')}
async function schoolFetch(route,data,token=schoolToken,timeoutMs=20000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);try{const r=await fetch(route,{method:data?'POST':'GET',headers:{'content-type':'application/json',...(token?{authorization:'Bearer '+token}:{})},...(data?{body:JSON.stringify(data)}:{}),signal:controller.signal,keepalive:route==='/api/action',cache:'no-store'});const out=await r.json();if(!r.ok)throw Object.assign(new Error(out.error||'요청을 완료하지 못했어요.'),{status:r.status});return out}finally{clearTimeout(timer)}}
function applySchool(data){const current=window.classroomData,samePlayer=current?.me?.id===data.me?.id;if(samePlayer&&data.me.version<current.me.version)data={...data,me:current.me};if(current?.room?.id===data.room?.id&&data.room.version<current.room.version)data={...data,room:current.room};if(current?.room?.id===data.room?.id&&current.mission&&(!data.mission||current.mission.revision>data.mission.revision))data={...data,mission:current.mission};const before=current?.me?.state?.history?.[0],after=data.me?.state?.history?.[0],tradeNotice=samePlayer&&!schoolPending&&after!==before&&/교환했어요|나눴어요|나눔 받았어요/.test(after||'')?after:'';window.classroomData=samePlayer?{...current,...data}:data;if(data.me){if(!samePlayer)state=data.me.state;else{for(const key of Object.keys(state))if(!(key in data.me.state))delete state[key];Object.assign(state,data.me.state)}state.day=data.room.day;state.repaired=state.repairDay===data.room.day;state.harvest=state.productionDay===state.day?state.dailyProduction:0}schoolOnline=true;render();refreshSchoolTradeDialog();if(tradeNotice)toast(tradeNotice)}
function refreshSchoolTradeDialog(){const dialog=$('#dialog');if(!dialog?.open)return;const give=$('#giveItem');if(give){const before=give.value;for(const option of give.options){const i=Number(option.value),count=schoolTradeStock(i);option.disabled=count<1;option.textContent=`${items[i]} · 보관 ${count}개`}if(give.selectedOptions[0]?.disabled)give.value=[...give.options].find(o=>!o.disabled)?.value||before;const max=Math.max(1,schoolTradeStock(Number(give.value))||0),qty=$('#giveQty');qty.max=String(max);if(Number(qty.value)>max)qty.value=String(max);$('#postSchoolOffer').disabled=[...give.options].every(o=>o.disabled);return}const confirm=$('#confirmSchoolTrade'),offerId=dialog.dataset.marketOffer;if(!confirm||!offerId)return;const offer=classroomData.offers?.find(o=>o.id===offerId),feedback=$('#marketDialogFeedback');if(!offer){confirm.disabled=true;feedback.textContent='이 교환 제안은 이미 완료되었어요. 창을 닫고 다시 확인해 주세요.';return}if(offer.seller===classroomData.me.id)return;const gift=offer.want_qty===0,have=gift?0:schoolTradeStock(offer.want_item),stock=$('#marketMeetingStock');if(stock)stock.textContent=gift?'내가 줄 물건 없음':`내 보관함 ${have}개`;const short=!gift&&have<offer.want_qty;confirm.disabled=short||schoolPending;if(short)feedback.textContent='교환할 물건이 부족해요.';else if(feedback.textContent==='교환할 물건이 부족해요.')feedback.textContent=''}
save=function(){if(!window.classroomActive)baseSchoolSave()};weather=function(){return window.classroomActive?weatherList[classroomData.room.weather]:baseWeather()};marketOpen=function(){return window.classroomActive?classroomData.room.market:baseMarket()};farmBlocked=function(){return window.classroomActive&&(classroomData.room.paused||!schoolOnline)||baseBlocked()};quiz=function(kind='daily'){schoolQuiz=kind;baseQuiz(kind)};
render=function(){baseSchoolRender();if(!window.classroomActive)return;const r=classroomData.room;classroomBar.hidden=false;classroomBar.innerHTML=`<b>학급 ${escapeHtml(r.code)} · ${escapeHtml(state.name)}</b><span>${escapeHtml(r.phase)} · ${r.paused?'수업 일시정지':'활동 중'}</span><span class="connection ${schoolOnline?'':'bad'}">${schoolPending?'저장 확인 중…':schoolOnline?'서버 연결됨':'연결 끊김 · 행동 잠금'}</span><button id="schoolReconnect">새로 확인</button><a class="school-link" href="teacher.html" target="_blank" rel="noopener">교사 화면</a>`;$('#schoolReconnect').onclick=refreshSchool;$('#nextDay').disabled=true;$('#nextDay').textContent='교사가 날짜 조절';$('#phaseDesc').textContent=`${r.paused?'교사가 수업을 일시정지했어요.':'학급과 함께 활동 중이에요.'} ${r.market?'장터가 열려 있어요.':'장터 개장을 기다려 주세요.'}`;$('#seasonBadge').textContent=r.phase;$('#reset').textContent='학급에서 나가기';document.querySelector('footer span:nth-child(2)').textContent='학급 공동 플레이 · 재고와 거래는 서버에 저장됩니다.'};
renderPanel=function(){if(!window.classroomActive){baseSchoolPanel();return}if(tab==='work'){baseSchoolPanel();const j=state.job;const div=document.createElement('div');div.className='school-prod';div.innerHTML=`<b>${symbols[j]} ${jobs[j].name}의 일</b><p>직업 생산은 하루 3회. 상추밭 재배와 별도로 내 생산물을 준비해요.</p><button class="wide" data-school-action="produce">${items[j]} 생산 · ${state.harvest}/3회</button>`;$('#panel').append(div);if(state.logistics?.shipment||state.logistics?.warehouse?.some(Boolean)||state.stock.slice(0,4).some(Boolean))$('#panel').insertAdjacentHTML('beforeend',coldChainPanel());return}if(tab==='market'){const d=classroomData;$('#panel').innerHTML=`<span class="eyetag">우리 반 실제 장터</span><h2>${d.room.market?'장터가 열렸어요':'장터 개장 준비'}</h2><p>제안한 물건은 장터에 보관돼요. 교환하거나, 받는 물건 없이 친구에게 나눠 줄 수 있어요.</p><button class="primary wide" id="newSchoolOffer" ${!d.room.market?'disabled':''}>교환 제안 올리기</button>${d.offers.length?d.offers.map(o=>`<div class="school-offer"><b>${escapeHtml(o.seller_name)}</b><p>${symbols[o.give_item]} ${items[o.give_item]} ${o.give_qty}개 ${o.want_qty===0?'→ 나눔':`↔ ${symbols[o.want_item]} ${items[o.want_item]} ${o.want_qty}개`}</p><button data-school-offer="${o.id}" data-offer-kind="${o.seller===d.me.id?'cancel':'accept'}" ${o.seller!==d.me.id&&!d.room.market?'disabled':''}>${o.seller===d.me.id?'내 제안 취소':'교환 내용 확인'}</button></div>`).join(''):'<p>아직 올라온 제안이 없어요. 첫 제안을 만들어 보세요.</p>'}`;$('#newSchoolOffer').onclick=newSchoolOffer;return}const r=classroomData.room;$('#panel').innerHTML=`<span class="eyetag">함께 차리는 식탁</span><h2>우리 반 공동 미션</h2><p>각 물건 ${r.goal}개를 함께 모아요. 기여한 물건은 활동 기록에 남아요.</p>${items.slice(0,4).map((n,i)=>`<div class="offer"><b>${symbols[i]} ${n} ${r.coop[i]}/${r.goal}</b><button data-school-donate="${i}" ${r.phase!=='협력'||state.stock[i]<1?'disabled':''}>1개 보태기</button></div>`).join('')}${r.coop.every(n=>n>=r.goal)?'<div class="notice">🎉 우리 반이 공동 식탁을 완성했어요!</div>':''}${weather().name.includes('폭우')&&!state.repaired?'<button class="wide secondary" data-action="repair">안전 복구 미션</button>':''}`};
async function performSchoolAction(payload,inline=false){const quiet=payload.action==='quiz'||payload.action==='repair'||inline;window.schoolLastActionError=null;if(schoolPending){window.schoolLastActionError='앞선 작업을 저장 중이에요. 잠시 뒤 다시 시도해 주세요.';if(!quiet)toast(window.schoolLastActionError);return false}if(!schoolOnline){window.schoolLastActionError='연결을 먼저 복구해 주세요.';if(!quiet)toast(window.schoolLastActionError);return false}schoolPending=true;window.classroomSaving=true;payload.requestId=payload.requestId||requestId();sessionStorage.setItem('village-pending-command',JSON.stringify(payload));render();try{let result;for(let i=0;i<3;i++){try{result=await schoolFetch('/api/action',payload);break}catch(e){if(e.status)throw e;if(i===2)throw e;await new Promise(r=>setTimeout(r,500*(i+1)))}}sessionStorage.removeItem('village-pending-command');applySchool(result);return true}catch(e){if(e.status){sessionStorage.removeItem('village-pending-command');window.schoolLastActionError=e.message;if(!quiet)toast(e.message);try{applySchool(await schoolFetch('/api/state'))}catch{}}else{schoolOnline=false;window.schoolLastActionError='연결이 끊겼어요. 다시 연결한 뒤 시도해 주세요.';if(!quiet)toast('연결이 끊겼어요. 같은 요청으로 복구하므로 물건이 두 번 처리되지 않아요.')}return false}finally{schoolPending=false;window.classroomSaving=false;render()}}
function schoolAction(payload,inline=false){if(schoolPending){window.schoolLastActionError='앞선 작업을 저장 중이에요. 잠시 뒤 다시 시도해 주세요.';if(!['quiz','repair'].includes(payload.action)&&!inline)toast(window.schoolLastActionError);return Promise.resolve(false)}const produced=payload.action==='produce'&&Number.isInteger(state.job)?{item:state.job,before:schoolTradeStock(state.job)}:null;const promise=performSchoolAction(payload,inline).then(ok=>{if(ok&&produced){const amount=schoolTradeStock(produced.item)-produced.before;toast(amount>0?`${items[produced.item]} ${amount}개를 얻었어요. 보관함에서 확인해 보세요.`:'직업 생산을 마쳤어요. 보관함을 확인해 보세요.')}return ok});window.pendingSchoolSave=promise;promise.finally(()=>{if(window.pendingSchoolSave===promise)window.pendingSchoolSave=null});return promise}
function refreshSchool(){if(!window.classroomActive||schoolPending)return;if(schoolRefreshing)return schoolRefreshing;schoolRefreshing=(async()=>{try{const pending=sessionStorage.getItem('village-pending-command');if(pending){schoolOnline=true;await schoolAction(JSON.parse(pending));return}applySchool(await schoolFetch('/api/state'))}catch(e){schoolOnline=false;if(e.status===401){schoolToken='';sessionStorage.removeItem('village-student-token');entrySchool()}render()}finally{schoolRefreshing=null}})();return schoolRefreshing}
function entrySchool(){
 if($('#dialog').open)close();
 modal(`<span class="eyebrow">Shiny Village</span><h2>마을에 들어가기</h2><p class="entry-intro">선생님이 준 입장 링크나 QR을 열면 바로 들어옵니다. 코드를 받았다면 아래에 입력하세요.</p><section class="class-entry"><b>우리 반 학생</b><form id="schoolEntry" class="school-entry"><label>학급 코드<input id="roomCode" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="6" placeholder="예: E02B01" required autofocus></label><label>내 입장 코드<input id="studentCode" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="48" placeholder="선생님이 준 코드" required></label><label class="remember-device"><input id="rememberDevice" type="checkbox"> 내 전용 기기에서만 이 학생 계정 기억하기</label><p class="school-error" id="entryError" role="alert"></p><button class="primary" type="submit">우리 반 들어가기</button></form></section><section class="trial-entry"><div><b>코드가 없나요?</b><p>연습 친구와 먼저 둘러볼 수 있어요.</p></div><button id="trialEntry" type="button">체험하기</button></section><p id="trialError" role="status"></p><button id="localDemo" type="button" hidden>인터넷 없이 농사만 연습</button><p class="entry-footer">선생님이신가요? <a id="teacherEntry" href="teacher.html">교사 운영실로 가기</a></p>`);
 $('#roomCode').focus();
 $('#trialEntry').onclick=async()=>{const button=$('#trialEntry');button.disabled=true;button.textContent='체험 마을에 입장 중…';$('#trialError').textContent='';$('#localDemo').hidden=true;try{let key=sessionStorage.getItem('village-trial-key');if(!key){key=requestId();sessionStorage.setItem('village-trial-key',key)}const data=await schoolFetch('/api/trial',{key},'');sessionStorage.removeItem('village-pending-command');schoolToken=data.token;sessionStorage.setItem('village-student-token',schoolToken);window.classroomActive=true;close();applySchool(data);startSchoolPolling()}catch(e){$('#trialError').textContent=e.status?e.message:'체험 서버에 연결하지 못했어요. 다시 시도하거나 농사만 연습해 보세요.';$('#localDemo').hidden=false}finally{button.disabled=false;button.textContent='체험하기'}};
 $('#schoolEntry').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('button');submit.disabled=true;try{const data=await schoolFetch('/api/join',{roomCode:$('#roomCode').value,code:$('#studentCode').value},'');if(data.teacher){$('#entryError').textContent='교사 코드는 아래의 교사 운영실에서 사용해 주세요.';return}window.StudentMemory.remember($('#rememberDevice').checked);schoolToken=data.token;sessionStorage.setItem('village-student-token',schoolToken);window.classroomActive=true;close();applySchool(data);startSchoolPolling()}catch(error){$('#entryError').textContent=error.status?error.message:'서버 연결을 확인해 주세요. 코드 없이 체험하기는 사용할 수 있어요.'}finally{submit.disabled=false}};
 $('#localDemo').onclick=()=>{window.classroomActive=false;close();if(state.job===null)showJobs();else render()};
}
const originalEntrySchool=entrySchool;
entrySchool=function(){
 originalEntrySchool();
 const saved=window.StudentMemory.read();
 if(!saved)return;
 const card=document.createElement('section');card.className='remembered-student';
 card.innerHTML=`<b>지난번에 들어온 학생</b><p>${escapeHtml(saved.name)} · 학급 ${escapeHtml(saved.room)}</p><p>내 계정이 맞는지 확인해 주세요. 공용 기기라면 위에서 내 입장 코드를 입력하세요.</p><button type="button" class="secondary" id="resumeStudent">${escapeHtml(saved.name)} 계정으로 들어가기</button><button type="button" class="quiet" id="forgetStudent">이 기기에서 기억 지우기</button>`;
 document.querySelector('.class-entry').after(card);
 $('#roomCode').value=saved.room;
 $('#resumeStudent').onclick=async()=>{const button=$('#resumeStudent');button.disabled=true;button.textContent='계정 확인 중…';try{const data=await schoolFetch('/api/state',undefined,saved.token);schoolToken=saved.token;sessionStorage.setItem('village-student-token',schoolToken);window.classroomActive=true;close();applySchool(data);startSchoolPolling()}catch{window.StudentMemory.forget();card.remove();$('#entryError').textContent='지난 계정을 확인할 수 없어요. 선생님이 준 코드로 다시 들어가 주세요.'}finally{button.disabled=false;button.textContent=`${saved.name} 계정으로 들어가기`}};
 $('#forgetStudent').onclick=()=>{window.StudentMemory.forget();card.remove();$('#studentCode').focus()};
};
function newSchoolOffer(){
 const available=items.map((_,i)=>schoolTradeStock(i));
 const first=available.findIndex(n=>n>0),wanted=items.findIndex((_,i)=>i!==first);
 modal(`<h2>교환·나눔 제안하기</h2><p>주는 물건은 친구가 받거나 내가 취소할 때까지 장터에 맡겨집니다.</p><div class="school-form"><label>내가 줄 물건<select id="giveItem" aria-label="주는 물건">${items.map((n,i)=>`<option value="${i}" ${available[i]?'':'disabled'} ${i===first?'selected':''}>${n} · 보관 ${available[i]}개</option>`).join('')}</select></label><label>주는 수량<input id="giveQty" type="number" min="1" max="${Math.max(1,available[first]||0)}" value="1" aria-label="주는 수량"></label><label class="market-gift-choice"><input id="schoolGift" type="checkbox"> 받는 물건 없이 친구에게 나눠 주기</label><label data-market-want>받을 물건<select id="wantItem" aria-label="받는 물건">${items.map((n,i)=>`<option value="${i}" ${i===wanted?'selected':''}>${n}</option>`).join('')}</select></label><label data-market-want>받는 수량<input id="wantQty" type="number" min="1" max="50" value="1" aria-label="받는 수량"></label></div><p id="marketDialogFeedback" role="alert" class="school-error">${first<0?'보관함에 줄 물건이 없어요. 내 농장에서 상추를 수확한 뒤 다시 와 주세요.':''}</p>${first<0?'<button type="button" id="marketGoFarm">내 농장으로 가기</button>':''}<div class="dialog-actions"><button data-close>취소</button><button id="postSchoolOffer" class="primary" ${first<0?'disabled':''}>제안 올리기</button></div>`);
 const give=$('#giveItem'),giveQty=$('#giveQty'),want=$('#wantItem'),wantQty=$('#wantQty'),gift=$('#schoolGift'),feedback=$('#marketDialogFeedback'),submit=$('#postSchoolOffer');
 gift.onchange=()=>{document.querySelectorAll('[data-market-want]').forEach(label=>label.hidden=gift.checked);want.disabled=wantQty.disabled=gift.checked;feedback.textContent=''};
 if($('#marketGoFarm'))$('#marketGoFarm').onclick=()=>{close();gameNavigate('farm')};
 give.onchange=()=>{giveQty.max=String(Math.max(1,available[Number(give.value)]||0));giveQty.value=String(Math.min(Math.max(1,Number(giveQty.value)||1),Number(giveQty.max)));feedback.textContent=''};
 for(const field of [giveQty,want,wantQty])field.oninput=()=>{feedback.textContent=''};
 submit.onclick=async()=>{const giving=Number(give.value),quantity=Number(giveQty.value),receiving=Number(want.value),requested=Number(wantQty.value);
  if(!gift.checked&&giving===receiving){feedback.textContent='서로 다른 물건을 선택해 주세요.';return}
  if(!Number.isInteger(quantity)||quantity<1||quantity>available[giving]){feedback.textContent='제안할 물건이 부족해요.';return}
  if(!gift.checked&&(!Number.isInteger(requested)||requested<1||requested>50)){feedback.textContent='받을 수량을 1~50개로 입력해 주세요.';return}
  submit.disabled=true;submit.textContent='제안 확인 중…';feedback.textContent='제안을 저장하고 있어요.';
  const ok=await schoolAction({action:'offer',giveItem:giving,giveQty:quantity,...(gift.checked?{gift:true}:{wantItem:receiving,wantQty:requested})},true);
  if(ok){close();toast(gift.checked?'나눔 제안을 올렸어요. 친구가 받으면 보관함으로 전해집니다.':'교환 제안을 올렸어요. 친구가 수락하면 물건이 교환됩니다.')}else{feedback.textContent=window.schoolLastActionError||'제안을 저장하지 못했어요. 다시 시도해 주세요.';submit.disabled=false;submit.textContent='제안 올리기'}
 };
}
document.addEventListener('click',async e=>{if(!window.classroomActive)return;const b=e.target.closest('button');if(!b)return;let handled=true,payload=null;const plot=b.closest('[data-plot]');if(plot){const i=Number(plot.dataset.plot),stage=plotStage(state.farm.plots[i]);payload={action:stage===0?'plant':stage===1?'water':stage===4?'harvest':'',plot:i}}else if(b.id==='confirmFarmSell')payload={action:'sell',item:0,qty:Number($('#sellCount').value)};else if(b.id==='expandFarm'){const cost=state.farm.plots.length===6?40:state.farm.plots.length===8?60:80;modal(`<h2>밭 2칸을 넓힐까요?</h2><p>${cost}코인이 필요해요.</p><div class="dialog-actions"><button data-close>취소</button><button id="confirmSchoolExpand" class="primary">확장하기</button></div>`)}else if(b.id==='confirmSchoolExpand')payload={action:'expand'};else if(b.dataset.coldAction){payload={action:b.dataset.coldAction};if(payload.action==='shipment_pack'){payload.item=Number($('#coldItem')?.value);payload.qty=Number($('#coldQty')?.value)}else payload.shipmentId=state.logistics?.shipment?.id;}else if(b.dataset.schoolAction)payload={action:b.dataset.schoolAction};else if(b.dataset.schoolDonate!==undefined)payload={action:'donate',item:Number(b.dataset.schoolDonate),qty:1};else if(b.dataset.schoolOffer){const id=b.dataset.schoolOffer,kind=b.dataset.offerKind;modal(`<h2>${kind==='cancel'?'제안을 취소할까요?':'이 교환을 수락할까요?'}</h2><p>${kind==='cancel'?'장터에 맡긴 물건이 돌아옵니다.':'상대가 맡긴 물건을 받고, 요청한 물건을 보내요.'}</p><div class="dialog-actions"><button data-close>돌아가기</button><button id="confirmSchoolTrade" class="primary">확정하기</button></div>`);$('#confirmSchoolTrade').onclick=async()=>{if(await schoolAction({action:kind,offer:id}))close()}}else if(b.dataset.answer!==undefined)payload={action:schoolQuiz==='repair'?'repair':'quiz',answer:Number(b.dataset.answer)};else if(b.dataset.action==='upgrade')payload={action:'upgrade'};else if(b.dataset.action==='harvest')payload={action:'produce'};else if(b.dataset.action==='sell')payload={action:'sell',item:state.job,qty:1};else if(b.id==='jobs'){window.showSchoolCareers?.()}else if(b.dataset.schoolJob!==undefined)payload={action:'job',job:Number(b.dataset.schoolJob)};else if(b.id==='reset'){window.logoutStudent()}else if(b.id==='nextDay'){}else handled=false;
if(handled){e.preventDefault();e.stopImmediatePropagation();if(payload?.action){const repair=payload.action==='repair';const ok=await schoolAction(payload,repair);if(repair){if(ok){if($('#dialog').open)close();toast('안전 복구 완료! 밭이 다시 열렸어요.')}else{const reasons={0:'젖은 전선을 만지면 감전될 수 있어요. 위험 구역에서 떨어져 전문 기술자에게 알려 주세요.',2:'젖은 전기 설비를 계속 쓰면 감전이나 화재가 날 수 있어요. 사용을 멈추고 전문가에게 알려 주세요.'};const feedback=$('#feedback');if(feedback)feedback.textContent=reasons[payload.answer]||window.schoolLastActionError||'안전한 대응을 다시 골라 주세요.'}}else if(ok&&['sell','expand','quiz','job'].includes(payload.action)&&$('#dialog').open)close()}return}if(b.dataset.tab){const place=b.dataset.tab;setTimeout(()=>schoolAction({action:'place',place}),0)}},true);
function startSchoolPolling(){schoolPoll?.();schoolPoll=ShinyPolling.start(refreshSchool,'school',()=>!document.hidden&&window.classroomActive&&document.body.dataset.screen!=='market')}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&window.classroomActive)refreshSchool()});window.addEventListener('online',refreshSchool);window.addEventListener('offline',()=>{schoolOnline=false;if(window.classroomActive)render()});
if(schoolToken){window.classroomActive=false;schoolFetch('/api/state').then(data=>{window.classroomActive=true;close();applySchool(data);startSchoolPolling();if(sessionStorage.getItem('village-pending-command'))refreshSchool()}).catch(error=>{if(error.status===401&&window.StudentMemory.read()?.token===schoolToken)window.StudentMemory.forget();schoolToken='';sessionStorage.removeItem('village-student-token');entrySchool();if(window.StudentMemory.linkAttempted)$('#entryError').textContent='학생 입장 링크가 맞지 않아요. 선생님께 다시 확인해 주세요.'}).finally(()=>window.villageBootReady?.('account'))}else{entrySchool();if(window.StudentMemory.linkAttempted)$('#entryError').textContent='학생 입장 링크가 맞지 않아요. 선생님께 다시 확인해 주세요.';window.villageBootReady?.('account')};


// Keep the walkthrough available after entry and refresh, without interrupting play.
const trialGuide=document.createElement('details');trialGuide.className='trial-guide';trialGuide.hidden=true;
let trialGuideKey='';trialGuide.addEventListener('toggle',()=>{if(!trialGuide.open&&trialGuide.dataset.presented==='1'){if(trialGuideKey)localStorage.setItem(trialGuideKey,'seen');trialGuide.hidden=true;trialGuide.dataset.manual=''}});
trialGuide.innerHTML='<summary>🌱 체험 마을 · 처음 시작하는 방법</summary><p>실제 학생이 아닌 <b>연습 친구</b>와 활동해요. 실제 학급 기록에는 반영되지 않아요.</p><ol><li><b>내 밭</b>에서 밭을 선택한 뒤 밭 위에 나타나는 심기·물 주기·수확 버튼을 눌러요.</li><li><b>장터</b>에서 연습 친구의 교환 제안을 수락해 보세요. 상추 1개로 우유나 사과를 받아요.</li><li><b>활동 → 공동 도시락</b>에서 수확물을 나누고, 메뉴의 <b>수입·기부 현황</b>에서 기록을 확인해요.</li><li>활동의 <b>진로 책장</b>에서 퀴즈를 풀고, 위쪽 <b>별빛도서관 탭</b>에서 공부를 시작해 보세요.</li></ol><p>체험 마을은 장터와 협력이 열린 1일차예요. 실제 수업에서는 선생님이 날짜를 조절합니다. 메뉴의 내 정보·설정에서 로그아웃하면 학급 코드로 입장할 수 있어요.</p>';
document.querySelector('main').before(trialGuide);
const trialApplySchool=applySchool;applySchool=function(data){trialApplySchool(data);window.StudentMemory.save(data,schoolToken);const isTrial=!!data.me?.state?.trial;trialGuideKey='shiny-guide-seen:'+(data.me?.id||'practice');const seen=localStorage.getItem(trialGuideKey)==='seen';trialGuide.hidden=!isTrial||(seen&&trialGuide.dataset.manual!=='1');if(isTrial&&!seen&&trialGuide.dataset.presented!=='1'){trialGuide.open=true;trialGuide.dataset.presented='1'}document.body.dataset.trial=String(isTrial)};
